\copy (SELECT i.ime, i.prezime, i.broj, i.pozicija, i.datum_rodenja, i.mjesto_rodenja, i.visina, i.broj_nastupa, i.broj_golova, k.ime AS prethodni_klub, k.grad AS grad_kluba FROM igraci i LEFT JOIN igrac_klub ik ON ik.prezime = i.prezime AND ik.ime_kluba <> '-' LEFT JOIN klubovi k ON k.ime = ik.ime_kluba ORDER BY i.prezime) TO '../data/igraci_dinama.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')